import openpyxl
from collections import OrderedDict
wb=openpyxl.load_workbook('/root/pwt11.xlsx', read_only=True)
ws=wb['Data']
header=[cell.value for cell in next(ws.iter_rows(min_row=1, max_row=1))]
idx={name:i for i,name in enumerate(header)}
# gather for Georgia
rows={}
for row in ws.iter_rows(min_row=2, values_only=True):
    if row[idx['countrycode']]=='GEO':
        year=row[idx['year']]
        if 1990 <= year <= 2023:
            rnna=row[idx['rnna']]
            rkna=row[idx['rkna']]
            rows[year]=(rnna, rkna)
# print sample
for y in sorted(rows)[:5]:
    print(y, rows[y])
print('count', len(rows))
